"use strict";(self.webpackChunk_N_E=self.webpackChunk_N_E||[]).push([[18893],{18893:(e,a,t)=>{t.d(a,{K_:()=>i,ZB:()=>s,b4:()=>r});let i=[{name:"Apple Minimal",slug:"apple-minimal",kind:"skill",version:"1.1.0",category:"Product",tags:["apple","minimal","product","typography","hardware","restraint"],tier:"pro",summary:"Build product landing pages with Apple's restraint: one idea per viewport, a giant type scale, generous negative space, and the product as the only hero.",whenToUse:"Use when the user asks for an Apple-like, minimal, premium or product-first landing page, names Apple, Linear, Vercel or Stripe as a reference, wants a very large hero type scale with generous whitespace, or asks to make a page feel expensive and uncluttered.",preview:'The Apple look is not "clean and minimal". It is a set of hard rules that most\nagents break instantly: exactly one idea per full-viewport section, a type scale\nthat jumps 3–4 steps between headline and body with no timid mid-sizes, an\n8-point spacing grid where vertical rhythm is measured in hundreds of pixels,\nand a colour palette of two neutrals plus the product\'s own colours.\n\nThis skill encodes the composition, type, spacing, motion, and most importantly,\nthe 38 anti-patterns that make an "Apple-inspired" page read as a cheap\nimitation: gradient headline text, glassmorphism everywhere, three-up feature\ncard grids, emoji icons, rounded-full pill badges above every heading, and\nsection padding that never exceeds `py-24`.',pairsWith:["prompt-saas","prompt-consumer-hardware","recipe-product-launch"],showcase:[{slug:"apple-minimal-hero",title:"The product as the only hero"},{slug:"apple-minimal-feature",title:"One idea per screen"},{slug:"apple-minimal-specs",title:"The one place density is allowed"}],outline:["1. The core idea","2. Page architecture","3. Type scale","4. Spacing system","5. Colour","6. Grid and containers","7. Navigation","8. Hero","9. Feature screens","10. Motion","11. Imagery and media","12. Buttons and links","13. Anti-patterns: what makes a page fail this style","14. Responsive behaviour","15. Accessibility","16. Performance","17. Implementation notes","18. Pairs well with React Bits Pro (optional)","19. Self-verification loop"],wordCount:4040,updated:"2026-09-29",changelog:"Corrected the contrast figures (\xa715) and the dark-mode button fill, which stays #0071E3 because white on #2997FF fails AA (\xa75, \xa712). Added matching a product photo's seamless to the page (\xa711), optical sizing (\xa73), the first- viewport rule (\xa78) and page-scroll scrubbing (\xa710). Showcase rebuilt by Claude Opus 5.5 at Max effort."},{name:"Corporate Trust",slug:"corporate-trust",kind:"skill",version:"1.1.0",category:"Enterprise",tags:["enterprise","b2b","fintech","trust","credibility","conversion"],tier:"pro",summary:"Build enterprise, finance and healthcare pages where credibility is the entire design objective: a conservative palette, a ranked trust ladder, dense organised proof and a demo-request form that a procurement committee finds legible.",whenToUse:"Use when the user is building an enterprise, B2B, finance, insurance, healthcare or government page, mentions compliance, SOC 2, HIPAA, procurement, security or trust signals, wants a demo-request or contact-sales flow, or asks for a conservative and credible design a committee will approve.",preview:'Enterprise trust is not "a blue gradient and three glass cards". It is a design\nlanguage justified by buyer psychology: long sales cycles, multiple stakeholders,\nand risk aversion. Credibility comes from real proof placed high, certifications\ntreated as design elements, dense but organised information, and motion so minimal\nit never looks like a consumer app trying too hard.\n\nThis skill encodes a conservative type scale, the exact blue-family palette and how\nto use it without looking generic, a ranked trust ladder, data and metrics\ntypography, density rules, mega-menu justification criteria, a demo-form spec, 34\nnumbered anti-patterns, an accessibility standard tied to procurement requirements,\nand a self-verification loop.',pairsWith:["prompt-fintech","prompt-saas","recipe-saas-homepage"],showcase:[{slug:"corporate-trust-hero",title:"Proof inside the first viewport"},{slug:"corporate-trust-proof",title:"A named result with its evidence"},{slug:"corporate-trust-security",title:"Certifications as design elements"}],outline:["1. The core idea","2. Page architecture for the enterprise buyer journey","3. Type scale","4. Colour system","5. The trust ladder","6. Data and metrics presentation","7. Density rules","8. Navigation and mega-menus","9. Hero and proof sections","10. Pricing, forms and motion","11. Anti-patterns: what makes a page fail this style","12. Responsive behaviour","13. Accessibility: procurement-grade","14. Performance","15. Implementation notes","16. Pairs well with React Bits Pro (optional)","17. Self-verification loop"],wordCount:4185,updated:"2026-09-29",changelog:"Added building the product surface in markup when there is no screenshot (\xa79), typeset seals when official marks cannot be used (\xa75), and a check that every repeated figure agrees (\xa717). Showcase rebuilt by Claude Opus 5.5 at Max effort."},{name:"Editorial",slug:"editorial",kind:"skill",version:"1.1.0",category:"Editorial",tags:["editorial","magazine","typography","serif","print","grid"],tier:"pro",summary:"Build magazine-grade editorial landing pages with a real serif display face, an asymmetric 12-column grid, controlled measure in ch, correct drop caps and pull quotes, hairline rules, and images that bleed and break the grid.",whenToUse:"Use when the user wants a magazine, publication, blog, essay or editorial layout, mentions serif display type, drop caps, pull quotes, hairline rules or asymmetric grids, or asks for a page that reads like print.",preview:'Editorial is not "a centred blog post in a serif font". It is a print-derived\ntypographic system - a serif display face paired with a text face at an exact\nmeasure, an asymmetric 12-column grid with real gutters, a baseline rhythm, and\npaper-and-ink colour that is never pure white on pure black. Drop caps and pull\nquotes are placed by rule, not decoration, and images bleed past the text column.\n\nThis skill encodes the column grid with exact spans and gutters, a type scale\nwith optical sizing and a measure in ch for every role, the correct way to build\na drop cap and a pull quote, a webfont loading strategy that avoids layout shift,\na 32-item numbered anti-patterns list, and a self-verification loop you run\nagainst your own render.',pairsWith:["prompt-agency","prompt-real-estate","recipe-agency-homepage"],showcase:[{slug:"editorial-spread",title:"An asymmetric opening spread over a full-bleed plate"},{slug:"editorial-feature",title:"One drop cap, one lifted pull quote, one bleed"},{slug:"editorial-index",title:"The issue index as ruled rows"}],outline:["1. The core idea","2. Page architecture","3. The column grid","4. Type scale","5. Vertical rhythm and baseline grid","6. Colour","7. Rules, hairlines and dividers","8. Drop caps and pull quotes","9. Image treatment and captions","10. Navigation","11. Masthead and hero","12. Article-style body sections","13. Anti-patterns - what makes a page fail this style","14. Responsive behaviour","15. Accessibility","16. Performance","17. Implementation notes","18. Pairs well with React Bits Pro (optional)","19. Self-verification loop"],wordCount:4690,updated:"2026-09-29",changelog:"Fixed the drop cap, whose CSS produced a two-line cap, with a derivation and verified values (\xa78). Fixed the hero example's kicker, which faked small caps (\xa717), and sized small caps by their height (\xa74). Showcase rebuilt by Claude Opus 5.5 at Max effort."},{name:"Luxury Serif",slug:"luxury-serif",kind:"skill",version:"1.1.0",category:"Premium",tags:["luxury","serif","editorial","fashion","hospitality","typography"],tier:"pro",summary:"Build high-end fashion, hospitality and jewellery pages where restraint reads as expensive: a high-contrast display serif, wide small-caps tracking, hairline rules and slow, deliberate motion.",whenToUse:"Use when the user is building a fashion, jewellery, hospitality, beauty, watch or luxury brand page, asks for an elegant, high-end, refined or understated aesthetic, or wants high-contrast serif type, wide small-caps tracking and slow deliberate motion.",preview:'The luxury look is not "a serif font and a gold button". It is a discipline of\nsubtraction: an enormous Didone display serif, almost no colour, positive tracking\nin exactly two places, full-bleed art-directed photography, and motion that barely\nmoves. Miss any piece and the page collapses into a SaaS template wearing Playfair\nDisplay.\n\nThis skill gives copy-pasteable Tailwind values for type scale, stroke contrast,\noptical-size guardrails, warm and cool neutral palettes, photography art direction,\n34 anti-patterns, AA-safe contrast rules that preserve hairlines, and a\nself-verification loop.',pairsWith:["prompt-real-estate","prompt-ecommerce-brand","recipe-agency-homepage"],showcase:[{slug:"luxury-serif-hero",title:"A full-bleed hero with the name in a Didone"},{slug:"luxury-serif-craft",title:"One material, beside a short caption"},{slug:"luxury-serif-residence",title:"A suite, named and priced once"}],outline:["1. The core idea","2. Page architecture","3. Typography: the display serif","4. Letter-spacing: the small-caps rule","5. Colour: warm and cool neutral palettes","6. Photography and art direction","7. Full-bleed and edge-to-edge treatment","8. Navigation","9. Hero","10. Product and property presentation","11. Motion","12. Buttons and links","13. Anti-patterns: what makes a page fail this style","14. Responsive behaviour","15. Accessibility: keeping the style AA-safe","16. Performance","17. Implementation notes","18. Pairs well with React Bits Pro (optional)","19. Self-verification loop"],wordCount:4477,updated:"2026-09-29",changelog:"Corrected the ink-secondary contrast figures, which pass (\xa715). Raised the Didone floor over photography (\xa73), aligned button and link tracking to the one small-caps value (\xa74, \xa712), and kept the solid nav off full-bleed images (\xa78). Showcase rebuilt by Claude Opus 5.5 at Max effort."},{name:"Neobrutalism",slug:"neobrutalism",kind:"skill",version:"1.1.0",category:"Expressive",tags:["neobrutalism","brutalist","expressive","borders","shadows","bold"],tier:"pro",summary:"Build loud neobrutalist landing pages with 3px black borders, hard offset shadows with zero blur, saturated flat colour blocks, and chunky type that physically moves when you press it.",whenToUse:"Use when the user asks for a brutalist, neobrutalist, bold, loud, playful or retro-web look, mentions thick black borders, hard offset shadows with no blur, or saturated flat colour blocks, or wants a page with strong personality rather than restraint.",preview:'Neobrutalism is not "a normal SaaS page with border-2 bolted on". It is a\nstrict physical system - hard offset shadows measured in exact pixels, an\nultra-heavy type scale that starts at 800 weight, four saturated colours\nallocated by role, and interactive states that translate the element into its\nown shadow on press. Get one value wrong and it collapses into a generic card\ngrid with black outlines.\n\nThis skill encodes the border and shadow mechanic in exact px and Tailwind\nclasses, a type scale table with weights most agents never reach, a 34-item\nnumbered anti-patterns list, the snappy stepped motion timings that separate\nreal neobrutalism from eased corporate animation, and a self-verification loop\nyou run against your own render.',pairsWith:["prompt-developer-tool","prompt-agency","recipe-saas-homepage"],showcase:[{slug:"neobrutalism-hero",title:"A 900-weight hero and a product block with hard shadows"},{slug:"neobrutalism-graph",title:"A bento where the numbers do the talking"},{slug:"neobrutalism-testimonials",title:"Hand-placed seller cards with duotone portraits"}],outline:["1. The core idea","2. Page architecture","3. Type scale","4. The border and shadow system","5. Colour system","6. Grid and containers","7. Navigation","8. Hero","9. Feature sections","10. Buttons and interactive states","11. Motion","12. Imagery treatment","13. Anti-patterns - what makes a page fail this style","14. Responsive behaviour","15. Accessibility","16. Performance","17. Implementation notes","18. Pairs well with React Bits Pro (optional)","19. Self-verification loop"],wordCount:4624,updated:"2026-09-29",changelog:"Corrected the contrast guidance: magenta, orange and green take ink and only blue takes white, with an exact table (\xa715). Clarified the two radius families (\xa74) and capped the hero at three lines (\xa78). Showcase rebuilt by Claude Opus 5.5 at Max effort."},{name:"Playful Motion",slug:"playful-motion",kind:"skill",version:"1.1.0",category:"Expressive",tags:["motion","spring","playful","animation","consumer","interaction"],tier:"pro",summary:"Build energetic consumer product pages driven by real spring physics: staggered reveals, scroll-linked transforms, oversized rounded geometry and micro-interactions that stay purposeful and never fight the reader.",whenToUse:"Use when the user wants an animated, energetic, bouncy or lively page, mentions spring physics, scroll-linked animation, staggered reveals or micro-interactions, or is building a consumer app, game, or creative product page.",preview:'Playful is not "add a bouncing arrow and animate everything". It is a motion\nsystem: spring configurations with exact stiffness, damping and mass per\ninteraction class, stagger timings measured in tens of milliseconds, scroll-linked\ntransform ranges, and a hard list of things that must never move. Miss the physics\nand you get the same `transition-all duration-300` on every element, which reads as\na template, not a personality.\n\nThis skill encodes the type and colour systems, a shape-language spec, the full\nmotion system with copy-pasteable `motion/react` spring configs, `prefers-reduced-motion`\nas a first-class design state, 34 numbered anti-patterns, a mobile motion budget, a\nvestibular-safety accessibility path, and a self-verification loop.',pairsWith:["prompt-fitness","prompt-ecommerce-brand","recipe-product-launch"],showcase:[{slug:"playful-motion-hero",title:"A product hero that springs in on a soft backdrop"},{slug:"playful-motion-demo",title:"The one interactive section: a real box builder"},{slug:"playful-motion-break",title:"The playful break: one shape, one line"}],outline:["1. The core idea","2. Page architecture","3. Type scale","4. Colour system","5. Shape language","6. The motion system","7. prefers-reduced-motion as a design state","8. Navigation","9. Hero","10. Feature sections and imagery","11. Anti-patterns: what makes a page fail this style","12. Responsive behaviour and mobile motion budget","13. Accessibility: vestibular safety and focus","14. Performance","15. Implementation notes","16. Pairs well with React Bits Pro (optional)","17. Self-verification loop"],wordCount:4183,updated:"2026-09-29",changelog:"Replaced the useReducedMotion() render branch, which caused hydration mismatches, with MotionConfig and a useSyncExternalStore hook (\xa77, \xa715, \xa719). Added contrast figures for bright brand colours (\xa74), elliptical arch radii (\xa75), the useScroll target note (\xa76) and the configurator as the canonical demo (\xa710). Showcase rebuilt by Claude Opus 5.5 at Max effort."},{name:"Swiss Grid",slug:"swiss-grid",kind:"skill",version:"1.1.0",category:"Systematic",tags:["swiss","grid","typographic","modular","grotesque","systematic"],tier:"pro",summary:"Build landing pages in the International Typographic Style: a visible 12-column modular grid, flush-left grotesque type at three sizes, and one accent used as data.",whenToUse:"Use when the user asks for a Swiss, International Typographic, modernist, systematic or grid-based design, names Helvetica, modular grids, baseline alignment or Muller-Brockmann, or wants a rigorous flush-left layout with mathematical spacing and a visible column structure.",preview:'Swiss design is not "Helvetica plus whitespace". It is a mathematical system\nagents rarely fake: a modular grid for every element, three type sizes from one\n8px unit, flush-left ragged-right setting with centred text banned, and one accent\ncolour used as information, not decoration. Break one rule and the page collapses\ninto a generic centred brochure.\n\nThis skill encodes grid mathematics (columns, gutters, margins and baseline at\nevery breakpoint), spacing as multiples of a base unit, 33 numbered anti-patterns,\nand copy-pasteable Tailwind for a reusable grid container that makes the structure\nvisible. It teaches the system, not the surface.',pairsWith:["prompt-saas","prompt-fintech","recipe-saas-homepage"],showcase:[{slug:"swiss-hero",title:"A flush-left hero with a figure drawn from the data"},{slug:"swiss-programme",title:"The whole timetable as one real table"},{slug:"swiss-posters",title:"A time-distance graph where the accent marks the crossings"}],outline:["1. The core idea","2. The modular grid","3. Making the grid visible","4. Type scale","5. Flush-left, ragged-right, and why centred text is banned","6. Spacing system","7. Colour","8. Navigation","9. Hero","10. Content sections and grid fields","11. Imagery","12. Motion","13. Anti-patterns: what makes a page fail this style","14. Responsive behaviour","15. Accessibility","16. Performance","17. Implementation notes","18. Pairs well with React Bits Pro (optional)","19. Self-verification loop"],wordCount:4520,updated:"2026-09-29",changelog:"Made the 1440px container consistent (\xa72), set line-heights in pixels so fluid type keeps the baseline (\xa76), placed nav items on explicit columns (\xa78), added figures drawn from the page's own data (\xa79) and corrected the accent contrast (\xa715). Showcase rebuilt by Claude Opus 5.5 at Max effort."},{name:"Terminal Dark",slug:"terminal-dark",kind:"skill",version:"1.2.0",category:"Technical",tags:["terminal","dark","developer","monospace","code","syntax"],tier:"free",summary:"Build developer-tool landing pages that read as software: dark-first surfaces, real compiling code as the hero, terminal motifs, hairline borders, and syntax as palette.",whenToUse:"Use when the user is building a developer tool, CLI, API, infrastructure, database or open-source landing page, mentions dark-first design, terminals, real code in the hero or syntax highlighting, or wants a page that reads as software rather than marketing.",preview:'The developer aesthetic is not "a SaaS page with dark mode". It is a specific\ndiscipline: designed dark-first with exact layered hex, monospace used only where it\nmeans something, real code that compiles as the hero visual, hairline borders instead\nof shadows that fail on dark, and a palette that is literally a syntax theme. Bolt\ndark: variants onto a light template and it reads as a costume.\n\nThis skill encodes the full dark colour system (background layers, surfaces, borders,\nfour text tiers, and a coherent syntax palette in exact hex), a code-block-as-hero\nspec, the install-command pattern, 34 numbered anti-patterns, the hard problem of code\non mobile solved explicitly, and copy-pasteable Tailwind.',pairsWith:["prompt-developer-tool","prompt-saas","recipe-saas-homepage"],showcase:[{slug:"td-hero",title:"Real code as the hero, sized to fit its frame"},{slug:"td-diff",title:"The migration: thirty lines of bookkeeping against the same sixteen-line file"},{slug:"td-figures",title:"A report drawn in the character cell: the bars are the numbers"}],outline:["1. The core idea","2. Page architecture","3. Colour system","4. Monospace: when it is right and when it is a mistake","5. Type scale","6. Code blocks as the hero","7. Terminal and command-line motifs","8. The install-command block","9. Feature sections: dense, not airy","10. Borders and elevation in a dark UI","11. Motion","12. Imagery and media","13. Anti-patterns: what makes a page fail this style","14. Responsive behaviour: code on mobile is the hard problem","15. Accessibility","16. Performance","17. Implementation notes","18. Pairs well with React Bits Pro (optional)","19. Self-verification loop"],wordCount:5881,updated:"2026-09-29",changelog:"Raised text-tertiary to #7B818B and syntax-comment to #7C8494, because the previous values failed AA (\xa73, \xa715, \xa717). Reconciled headline weights (\xa72.3, \xa75), sized code to its frame and required figures and code to agree (\xa76), and made the mobile scroll fade a mask (\xa714). Showcase rebuilt by Claude Opus 5.5 at Max effort."},{name:"Agency",slug:"agency",kind:"prompt",version:"1.1.0",category:"Services",tags:["agency","studio","services","portfolio","case-studies","enquiry"],tier:"pro",summary:"Build a studio site where the work is the pitch: selected projects, a real process, named people, and an enquiry form that filters for the clients you want.",whenToUse:"Use when the user is building a site for a design studio, creative agency, consultancy, freelance practice or production company, and needs selected client work, case studies, a process section, named people, or an enquiry form that qualifies leads.",preview:'Agency sites fail predictably: the agent writes a SaaS page, swaps\n"Start free" for "Get in touch", and calls it done. A services business converts\ndifferently. There is no signup or price. The buyer chooses people, the work\ncarries the argument, and the enquiry form is the funnel. Its fields decide whether\nyou get qualified briefs or spam.\n\nThis prompt covers positioning and specialism; selected-work presentation (grid\nversus list, project count, and what each case-study card must carry); a\nnon-generic process; team and credibility; logos and attributed testimonials;\nenquiry form fields and why each exists; budget qualification; and how to solve the\n"no published pricing" problem without looking evasive.',pairsWith:["skill-editorial","skill-luxury-serif","recipe-agency-homepage"],showcase:[{slug:"agency-editorial",title:"Rendered through skill-editorial"},{slug:"agency-luxury",title:"Rendered through skill-luxury-serif"},{slug:"agency-neobrutal",title:"Rendered through skill-neobrutalism"}],outline:["1. Before you write anything","2. Primary objective","3. User journey","4. Required page structure","5. Positioning and specialism","6. Selected work","7. The process section","8. Services presentation","9. Team and credibility","10. The enquiry form (the whole funnel)",'11. The "no pricing" problem',"12. Responsive priorities","13. Accessibility","14. Common mistakes to avoid","15. Completion checklist"],wordCount:3139,updated:"2026-09-29",changelog:"Added the hero flagship's caption (\xa76) and where the published floor belongs (\xa711). Showcase rebuilt by Claude Opus 5.5 at Max effort."},{name:"Consumer Hardware",slug:"consumer-hardware",kind:"prompt",version:"1.2.0",category:"Physical Product",tags:["hardware","consumer","ecommerce","product","specs","retail"],tier:"pro",summary:"Build a product page for a physical consumer device: desire before specs, one honest hero photograph, a spec table buyers actually read, and shipping, warranty and returns resolved before the visitor hunts for them.",whenToUse:"Use when the user is building a page for a physical product or device, mentions hardware, gadgets, specifications, dimensions, materials, pre-orders or shipping, or needs a spec table and product photography layout that sells desire before detail.",preview:"Hardware pages fail in a specific way: the agent writes a SaaS page and drops a\nproduct photo into it. Physical products need a different argument order: material\nand feel before the feature list, one honest hero photograph before any render, a\ndense specification table, and shipping, warranty, returns and compatibility\nanswered before the buyer has to look for them.\n\nThis prompt covers the audience model and desire-to-specs section order, product\nphotography specified shot by shot, conveying material and weight through a screen,\nthe variant configurator for desktop and mobile, one-time-purchase price anchoring,\npre-order and backorder honesty, warranty and repairability as trust signals,\ncertification and regulatory handling, comparison against the incumbent, and 34\nnumbered mistakes that make a hardware page read as dropshipping.",pairsWith:["skill-apple-minimal","recipe-product-launch"],showcase:[{slug:"hardware-apple",title:"Rendered through skill-apple-minimal"},{slug:"hardware-swiss",title:"Rendered through skill-swiss-grid"},{slug:"hardware-playful",title:"Rendered through skill-playful-motion"}],outline:["1. Before you write anything","2. Primary objective","3. User journey","4. Required page structure","5. Product photography","6. Conveying the physical object through a screen","7. Copy and specification tables","8. Variants and configuration","9. Price and value for a one-time purchase","10. Availability, shipping and pre-order honesty","11. Proof: reviews, press and comparison","12. Warranty, returns and repairability","13. Regulatory, certifications and compliance","14. Responsive priorities and accessibility","15. Common mistakes to avoid","16. Completion checklist"],wordCount:3298,updated:"2026-09-29",changelog:"Added matching the studio set to the page (\xa75) and swatches cut from each variant's own photograph (\xa78). Showcase rebuilt by Claude Opus 5.5 at Max effort, now through apple-minimal, swiss-grid and playful-motion."},{name:"Developer Tool",slug:"developer-tool",kind:"prompt",version:"1.1.0",category:"Software",tags:["developer","api","sdk","cli","open-source","docs"],tier:"pro",summary:"Build a landing page for engineers: real code in the hero, a copy-paste quickstart, honest benchmarks, credible open-source signals, and zero marketing tics that close tabs.",whenToUse:"Use when the user is building a landing page for a library, SDK, CLI, API, framework or developer platform, and needs a copy-paste quickstart, installation commands, honest benchmarks, open-source signals, or a page written for engineers.",preview:'Engineers are the most marketing-hostile audience on the internet. They evaluate a\ntool by reading its code, not its adjectives, and they close the tab the instant a\npage smells like it was written for a VP. A developer-tool page that leads with a\nvalue proposition instead of a runnable command has already lost the reader it\nwanted.\n\nThis prompt covers why the hero must contain real code or a real command, what that\ncode should demonstrate, the install/quickstart block, "time to first success" as a\ndesign constraint, docs as a conversion surface, open-source signalling done right,\ncredible benchmarks with disclosed methodology, fair comparison, developer-tool\npricing (free tiers, usage-based, self-host), the community section, language\ncoverage, and the exact marketing tics that make engineers bounce.',pairsWith:["skill-terminal-dark","skill-swiss-grid","recipe-saas-homepage"],showcase:[{slug:"devtool-terminal",title:"Rendered through skill-terminal-dark"},{slug:"devtool-swiss",title:"Rendered through skill-swiss-grid"},{slug:"devtool-neobrutal",title:"Rendered through skill-neobrutalism"}],outline:["1. Before you write anything","2. Primary objective","3. Why the hero must contain real code","4. What the hero code should demonstrate","5. Install and quickstart block","6. Time to first success as a design constraint","7. Documentation as a conversion surface","8. Open-source signalling","9. Performance and benchmark claims","10. Comparison against alternatives","11. Pricing for developer tools","12. Community and ecosystem","13. Responsive priorities","14. Accessibility","15. Marketing tics that make engineers close the tab","16. Completion checklist"],wordCount:2945,updated:"2026-09-29",changelog:"Added the request itself as the hero example for URL and HTTP products (\xa74). Showcase rebuilt by Claude Opus 5.5 at Max effort, now through terminal-dark, swiss-grid and neobrutalism."},{name:"Ecommerce Brand",slug:"ecommerce-brand",kind:"prompt",version:"1.1.0",category:"Commerce",tags:["ecommerce","dtc","product","conversion","mobile","checkout"],tier:"pro",summary:"Build a DTC product page where every unanswered question is a lost sale: hero shot, product story, sizing, variants, shipping and returns as conversion levers, honest reviews, and a mobile-first sticky add-to-cart.",whenToUse:"Use when the user is building a direct-to-consumer product or store page, mentions variants, sizing, shipping, returns, reviews or add-to-cart, or needs every purchase objection answered on the page itself.",preview:'A DTC product page has one job: turn a curious visitor into a buyer before a single\nunanswered question sends them away. Most agent-built store pages fail the same way:\na hero shot that hides the product, no answer to "will it fit me", shipping and\nreturns buried in the footer, and manufactured urgency that screams dropshipping.\n\nThis prompt defines the hero shot requirements, the origin-and-values story DTC\nbrands lead with, product detail and sizing done credibly, variant selection,\nshipping and returns as conversion levers, honest handling of a low review count,\nsubscription and bundle patterns, substantiated sustainability claims, the honest\nline on scarcity, sticky add-to-cart behaviour, mobile-first priorities, and 30\nmistakes that make a page feel like a dropshipping store.',pairsWith:["skill-luxury-serif","skill-playful-motion","recipe-product-launch"],showcase:[{slug:"bag-luxury",title:"Rendered through skill-luxury-serif"},{slug:"bag-playful",title:"Rendered through skill-playful-motion"},{slug:"bag-editorial",title:"Rendered through skill-editorial"}],outline:["1. Before you write anything","2. Primary objective","3. User journey","4. The hero product shot","5. Product story and values","6. Product detail and sizing","7. Reviews, UGC and honest social proof","8. Price and value justification","9. Shipping, returns and delivery transparency","10. Variants, subscriptions and bundles","11. Sustainability and ethical claims","12. Urgency and scarcity: the honest line","13. Add-to-cart and sticky behaviour","14. Mobile-first priorities and accessibility","15. Common mistakes to avoid","16. Completion checklist"],wordCount:2706,updated:"2026-09-29",changelog:"Added the fit line inside the size picker (\xa76), the honest bundle anchor (\xa78), and sold-out colours that are struck rather than faded (\xa710). Showcase rebuilt by Claude Opus 5.5 at Max effort, now through luxury-serif, playful-motion and editorial."},{name:"Fintech",slug:"fintech",kind:"prompt",version:"1.1.0",category:"Finance",tags:["fintech","finance","payments","banking","compliance","trust"],tier:"pro",summary:"Build a financial product page where trust is the design problem: licensing, deposit protection, security, fee transparency, and required risk disclosures placed to convert.",whenToUse:"Use when the user is building a page for a bank, broker, payments, lending, investing or crypto product, mentions regulation, licensing, deposit protection, fees, APR or risk disclosures, or needs required financial disclaimers placed where they are legally effective.",preview:"A fintech page has a problem no SaaS page has: the visitor is being asked to move\nmoney, and the internet has trained them to assume any slick money app is a scam.\nTrust is not a section. It is the whole design brief. Get the disclosures, the\nlicensing, and the fee transparency wrong and the page reads as fraud no matter how\ngood the visuals are.\n\nThis prompt covers the trust ladder specific to money (licensing, regulator\nregistration, deposit protection, custody, audits, security architecture), the\nrequired legal disclosures and risk warnings and how to place them without wrecking\nthe page, fee and APR transparency, how a consumer fintech page diverges from an\nAPI/infrastructure page, KYC expectation-setting, financial-grade social proof,\nincumbent comparison, and the specific tics that make a fintech page read as a scam.",pairsWith:["skill-corporate-trust","skill-swiss-grid","recipe-saas-homepage"],showcase:[{slug:"fintech-corporate",title:"Rendered through skill-corporate-trust"},{slug:"fintech-apple",title:"Rendered through skill-apple-minimal"},{slug:"fintech-neobrutal",title:"Rendered through skill-neobrutalism"}],outline:["1. Before you write anything","2. Primary objective","3. The trust ladder for money","4. Required disclosures and risk warnings","5. Fee transparency","6. Rate and APR presentation","7. Onboarding and KYC expectation-setting","8. Consumer vs infrastructure fintech","9. The security section","10. Social proof that works for money","11. Comparison against incumbents","12. Responsive priorities","13. Accessibility","14. Common mistakes that make a fintech page read as a scam","15. Completion checklist"],wordCount:3138,updated:"2026-09-29",changelog:"Added joint-account deposit protection (\xa73), the disclosure band under the hero (\xa74) and the exact worked example for deposits (\xa76). Showcase rebuilt by Claude Opus 5.5 at Max effort."},{name:"Fitness",slug:"fitness",kind:"prompt",version:"1.1.0",category:"Health",tags:["fitness","gym","coaching","membership","trial","conversion"],tier:"pro",summary:"Build a fitness page that converts an emotional decision into a booked trial: transformation framing without unfounded claims, schedule UI that works on mobile, honest proof, and transparent pricing.",whenToUse:"Use when the user is building a page for a gym, studio, personal trainer, coaching programme or fitness app, mentions class schedules, memberships, free trials, transformations or testimonials, or needs to turn an emotional decision into a booked session.",preview:"A fitness page sells self-image, not equipment. Most agent-built gym and coaching\npages fail the same way: a hero promise that would trigger a health regulator, a\nclass timetable that is unreadable on the phone every member actually uses, and\nbefore/after photos that read as fabricated the moment a real human looks at them.\n\nThis prompt defines the three distinct structures: physical gym, online coaching,\nand fitness app. It also covers the transformation promise done honestly, a\nconcrete schedule and timetable UI for desktop and mobile, the trial offer as the\nprimary conversion, trainer credibility rules, contract and cancellation\ntransparency, member proof with attribution, inclusive imagery, and 28\nfitness-specific mistakes to avoid.",pairsWith:["skill-playful-motion","skill-neobrutalism","recipe-product-launch"],showcase:[{slug:"fitness-swiss",title:"Rendered through skill-swiss-grid"},{slug:"fitness-playful",title:"Rendered through skill-playful-motion"},{slug:"fitness-editorial",title:"Rendered through skill-editorial"}],outline:["1. Before you write anything","2. Primary objective","3. User journey","4. Required page structure by business type","5. The transformation promise, honestly","6. Schedule and timetable UI","7. Programme and membership structure","8. The trial offer as the primary conversion","9. Trainer and coach credibility","10. Honest before/after and results imagery","11. Pricing and contract transparency","12. Location, hours and finding us","13. Accessibility and inclusivity","14. Common mistakes to avoid","15. Completion checklist"],wordCount:2942,updated:"2026-09-29",changelog:"Added a process promise tied to the offer (\xa75) and the next free sessions in the hero (\xa78). Showcase rebuilt by Claude Opus 5.5 at Max effort."},{name:"Real Estate",slug:"real-estate",kind:"prompt",version:"1.1.0",category:"Property",tags:["real-estate","property","listing","development","brokerage","gallery"],tier:"pro",summary:"Build a property page where imagery does the selling for a single listing, development launch, or brokerage, with a shot-ordered gallery, mobile-readable floor plans, spec tables, and a viewing-request conversion.",whenToUse:"Use when the user is building a page for a property listing, new development, brokerage or rental, mentions floor plans, photo galleries, viewings, neighbourhoods or agent contact, or needs imagery to carry the selling.",preview:"Property is a high-value, slow decision, and photography does most of the work.\nMost agent-built property pages fail on the parts that matter: a weak first image\nthat kills the listing before the scroll, floor plans that are unreadable on a\nphone, missing spec facts a serious buyer needs, and a viewing form buried below\nthe fold.\n\nThis prompt defines the three distinct structures for single listings, development\nlaunches, and brokerages, plus the gallery shot list and ordering, floor-plan\npresentation for mobile, the specification table, neighbourhood context that works\nwithout a dead map, availability and unit-selector interfaces, price-on-application\nlogic, agent credibility, a general pattern for legal notices, and 30 mistakes that\nmake a property page feel like a scam listing.",pairsWith:["skill-luxury-serif","skill-editorial","recipe-agency-homepage"],showcase:[{slug:"estate-luxury",title:"Rendered through skill-luxury-serif"},{slug:"estate-corporate",title:"Rendered through skill-corporate-trust"},{slug:"estate-terminal",title:"Rendered through skill-terminal-dark"}],outline:["1. Before you write anything","2. Primary objective","3. Structure by page type","4. Photography and gallery","5. Floor plans","6. Specification and detail table","7. Location and neighbourhood","8. Virtual tours, video and viewing conversion","9. Availability and unit selectors (developments)","10. Price presentation","11. Legal and regulatory notices","12. Agent and firm credibility","13. Accessibility and performance","14. Common mistakes to avoid","15. Completion checklist"],wordCount:2844,updated:"2026-09-29",changelog:"Added one property from one shoot (\xa74) and the open house in the hero (\xa78). Showcase rebuilt by Claude Opus 5.5 at Max effort."},{name:"SaaS Landing Page",slug:"saas",kind:"prompt",version:"1.1.0",category:"Software",tags:["saas","b2b","software","conversion","signup","trial"],tier:"pro",summary:"Build a SaaS landing page that converts self-serve signups through problem framing, product proof, objection handling, pricing clarity, and a single dominant CTA.",whenToUse:"Use when the user is building a landing page for a software subscription product, mentions free trials, signup, pricing tiers, integrations or dashboards, or needs problem framing, product proof and objection handling aimed at self-serve conversion.",preview:'A SaaS landing page has one job: get a qualified visitor to start. Most\nagent-built SaaS pages fail because they describe the software instead of the\noutcome, bury the product behind three scrolls of abstract benefit copy, and\nscatter five competing CTAs across the page.\n\nThis prompt defines the audience model, the required page structure and section\norder, the exact questions each section must answer, the CTA hierarchy, the\ntrust ladder (and when each rung is a liability rather than an asset), pricing\npresentation rules, and 20+ SaaS-specific mistakes to avoid, from "our AI-powered\nplatform" headlines to feature tables nobody reads.',pairsWith:["skill-apple-minimal","recipe-product-launch"],showcase:[{slug:"saas-apple",title:"Rendered through skill-apple-minimal"},{slug:"saas-terminal",title:"Rendered through skill-terminal-dark"},{slug:"saas-corporate",title:"Rendered through skill-corporate-trust"}],outline:["1. Before you write anything","2. Primary objective","3. User journey","4. Required page structure","5. Content guidance","6. CTA strategy","7. Trust ladder","8. Pricing presentation","9. Navigation requirements","10. Responsive priorities","11. Accessibility","12. Industry-specific considerations","13. Common mistakes to avoid","14. Completion checklist"],wordCount:2577,updated:"2026-09-29",changelog:"Added the product's own artefact as the capability visual (\xa75). Showcase rebuilt by Claude Opus 5.5 at Max effort, now through apple-minimal, terminal- dark and corporate-trust."},{name:"Agency Homepage",slug:"agency-homepage",kind:"recipe",version:"1.2.0",category:"Marketing",tags:["agency","studio","homepage","portfolio","blocks"],tier:"pro",summary:"A tested 10-block arrangement that assembles a complete creative or technical studio homepage (positioning through enquiry) from React Bits Pro blocks in one prompt.",whenToUse:"Use when the user wants a complete studio or agency homepage assembled in one pass, from positioning through enquiry, rather than composing sections one at a time. Works with the React Bits Pro blocks or with the plain-markup fallback described for every section.",preview:"A recipe is a prompt with a bill of materials. This one produces a full studio\nhomepage from ten React Bits Pro blocks in a fixed order, built to convert a\nqualified enquiry rather than a signup, with the role of each block, the content\nit must carry, and the configuration the agent should apply.\n\nBecause the block set and order live as structured data in plan.json, the same\nrecipe drives an agent prompt today and the visual Landing Builder later. It ships\na content plan for every block, a harmonization pass that makes the ten\nindependently authored blocks read as one page, an adaptation guide for\ndesign-led versus engineering-led studios, guidance on pairing it with a visual\nskill, and a fallback path for projects without the Pro registry.",pairsWith:["skill-editorial","skill-luxury-serif","prompt-agency"],showcase:[{slug:"agency-recipe-page",title:"Common Room, assembled from ten blocks in plan order"},{slug:"agency-recipe-blocks",title:"The bill of materials: each block as it ships on the page"},{slug:"agency-recipe-harmony",title:"The harmonization pass, measured on the rendered page"}],outline:["1. When to use this recipe","2. The prompt","3. Block set and order","4. Content plan per block","5. The harmonization pass","6. Adapting the result","7. Pairing with a skill","8. Working without React Bits Pro","9. Completion checklist"],wordCount:3649,updated:"2026-09-29",changelog:"Corrected \xa75.4: social-proof-6 also animates on mount and about-1's timer runs from page load. Moved reduced motion to one root MotionConfig, and described how skill-editorial changes three \xa75 values (\xa77). Showcase rebuilt by Claude Opus 5.5 at Max effort: the assembled page, the bill of materials, and the \xa75.6 counts measured on the render."},{name:"Product Launch Page",slug:"product-launch",kind:"recipe",version:"1.2.0",category:"Launch",tags:["launch","product","waitlist","announcement","blocks"],tier:"pro",summary:"A tested block arrangement that assembles a full product-launch page from React Bits Pro blocks (announcement hero through waitlist capture) in one prompt.",whenToUse:"Use when the user wants a full product launch or announcement page assembled in one pass, including waitlist or pre-order capture, rather than composing sections one at a time. Works with the React Bits Pro blocks or with the plain-markup fallback described for every section.",preview:"A recipe is a prompt with a bill of materials. This one produces a complete\nproduct-launch page from eleven React Bits Pro blocks in a fixed order, with the\nrole of each block, the content it should carry, and the configuration the agent\nshould apply.\n\nBecause the block set and order are declared as structured data\n(`plan.json`), the same recipe drives an agent prompt today and the visual\nLanding Builder later. It ships a full harmonization pass that unifies type,\ncolour, layout and scroll motion across the blocks so they read as one page, plus\nan adaptation guide for the two common variants (pre-launch waitlist versus\navailable-now) and a fallback path for projects without the Pro registry.",pairsWith:["skill-apple-minimal","prompt-saas","prompt-consumer-hardware"],showcase:[{slug:"launch-recipe-page",title:"Eddy, assembled from eleven blocks in plan order"},{slug:"launch-recipe-blocks",title:"The bill of materials: each block as it ships on the page"},{slug:"launch-recipe-harmony",title:"The harmonization pass, measured on the rendered page"}],outline:["1. When to use this recipe","2. The prompt","3. Block set and order","4. Content plan per block","5. The harmonization pass","6. Launch mechanics: countdown, scarcity, and the day after","7. Adapting the result","8. Pairing with a skill","9. Working without React Bits Pro","10. Completion checklist"],wordCount:3764,updated:"2026-09-29",changelog:"Corrected social-proof-4 (a testimonial wall) and features-6 (a card grid) (\xa73, \xa74, \xa78), gave each launch branch its own install command with social- proof-4 included (\xa73), and covered the loops, reduced motion and a hero shader under a skill with its own accent (\xa75). Showcase rebuilt by Claude Opus 5.5 at Max effort: the assembled page, the bill of materials, and the \xa75.6 counts measured on the render."},{name:"SaaS Homepage",slug:"saas-homepage",kind:"recipe",version:"1.2.0",category:"Marketing",tags:["saas","homepage","marketing","conversion","blocks"],tier:"pro",summary:"A tested 13-block arrangement that assembles a complete self-serve B2B SaaS homepage (navigation through footer) from React Bits Pro blocks in one prompt.",whenToUse:"Use when the user wants an entire self-serve SaaS homepage assembled in one pass, from navigation through footer, rather than composing sections one at a time. Works with the React Bits Pro blocks or with the plain-markup fallback described for every section.",preview:"A recipe is a prompt with a bill of materials. This one produces a full\nself-serve SaaS homepage from thirteen React Bits Pro blocks in a fixed order,\nwith the role of each block, the content it must carry, and the configuration\nthe agent should apply.\n\nBecause the block set and order live as structured data in plan.json, the same\nrecipe drives an agent prompt today and the visual Landing Builder later. It\nships a content plan for every block, a harmonization pass that makes the\nthirteen independently authored blocks read as one page (type, colour, layout,\nmotion), an adaptation guide for product-led versus sales-assisted variants,\nguidance on pairing it with a visual skill, and a fallback path for projects\nthat do not have the Pro registry configured.",pairsWith:["skill-swiss-grid","skill-corporate-trust","prompt-saas"],showcase:[{slug:"saas-recipe-page",title:"Tern, assembled from thirteen blocks in plan order"},{slug:"saas-recipe-blocks",title:"The bill of materials: each block as it ships on the page"},{slug:"saas-recipe-harmony",title:"The harmonization pass, measured on the rendered page"}],outline:["1. When to use this recipe","2. The prompt","3. Block set and order","4. Content plan per block","5. The harmonization pass","6. Adapting the result","7. Pairing with a skill","8. Working without React Bits Pro","9. Completion checklist"],wordCount:3400,updated:"2026-09-29",changelog:"Corrected stats-3, which runs an endless drift rather than counters (\xa73, \xa75.4, \xa75.5), and moved reduced motion to one root MotionConfig (\xa75.4). Showcase rebuilt by Claude Opus 5.5 at Max effort: the assembled page, the bill of materials, and the \xa75.6 counts measured on the render."}],r={skill:"skills",prompt:"prompts",recipe:"recipes"};function s(e){let a=/^(skill|prompt|recipe)-(.+)$/.exec(e);if(a){var t,r;return t=a[1],r=a[2],i.find(e=>e.kind===t&&e.slug===r)}}}}]);